func newTrailBranchAddCmd() *cobra.Command {
	var baseBranch string
	var trailFlag string

	cmd := &cobra.Command{
		Use:   "add [branch-name]",
		Short: "Add a branch to the current trail",
		Long:  "Adds the current branch (or a named branch) to a trail. Uses stateless lookup to find the trail.",
		Args:  cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			repo, err := strategy.OpenRepository()
			if err != nil {
				return err
			}

			store := trail.NewStore(repo)

			// Determine branch name
			branchName := GetCurrentBranchName(repo)
			if len(args) > 0 {
				branchName = args[0]
			}
			if branchName == "" {
				return errors.New("could not determine branch name")
			}

			// Check if branch is already in a trail
			existing, existingEntry, _ := store.FindByBranch(branchName)
			if existing != nil && existingEntry != nil {
				fmt.Fprintf(cmd.ErrOrStderr(), "Warning: branch %q is already in trail %q\n", branchName, existing.Title)
				return nil
			}

			// Resolve which trail to add to
			var targetTrail *trail.Metadata
			if trailFlag != "" {
				targetTrail, _, _, _, err = store.Read(trail.ID(trailFlag))
				if err != nil {
					return fmt.Errorf("trail %s not found: %w", trailFlag, err)
				}
			} else {
				// Try to resolve from current branch context
				currentBranch := GetCurrentBranchName(repo)
				targetTrail, _, _ = store.FindByBranch(currentBranch)
				if targetTrail == nil {
					// Interactive picker or error
					return errors.New("cannot determine trail; use --trail <id> to specify")
				}
			}

			// Determine base
			if baseBranch == "" {
				baseBranch = getDefaultBranchName(repo)
			}

			// Generate branch entry UUID
			entryID, err := generateUUID()
			if err != nil {
				return fmt.Errorf("failed to generate branch ID: %w", err)
			}

			entry := trail.BranchEntry{
				ID:         entryID,
				Name:       branchName,
				BaseBranch: baseBranch,
				Status:     trail.BranchOpen,
				AddedAt:    time.Now().UTC(),
			}

			if err := store.Update(targetTrail.TrailID, func(m *trail.Metadata) {
				m.Branches = append(m.Branches, entry)
			}); err != nil {
				return fmt.Errorf("failed to add branch: %w", err)
			}

			fmt.Fprintf(cmd.OutOrStdout(), "Added branch %q to trail %q\n", branchName, targetTrail.Title)
			return nil
		},
	}

	cmd.Flags().StringVar(&baseBranch, "base", "", "Base branch for stacking (default: default branch)")
	cmd.Flags().StringVar(&trailFlag, "trail", "", "Trail ID to add branch to")

	return cmd
}

// generateUUID returns a random UUID string for branch entry IDs.
func generateUUID() (string, error) {
	b := make([]byte, 16)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return hex.EncodeToString(b), nil
}
```

